package com.codepathacademy.learning;
import com.codepathacademy.identity.AppUser;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="learning_data_conflict_resolutions") class ConflictResolution {@Id @GeneratedValue UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="import_id") LearningDataImport importAudit;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id") AppUser user;@Column(name="source_key")String sourceKey;@Column(name="operation_key")String operationKey;String resolution;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="note_id") PersonalNote note;@Column(name="expected_version")Long expectedVersion;@Column(name="resolved_at")Instant resolvedAt=Instant.now();protected ConflictResolution(){}ConflictResolution(LearningDataImport i,AppUser u,String s,String k,String r,PersonalNote n,Long v){importAudit=i;user=u;sourceKey=s;operationKey=k;resolution=r;note=n;expectedVersion=v;}}
